// Memória permanente de deduplicação
const staticData = $getWorkflowStaticData('global');
staticData.seenJobIds = staticData.seenJobIds || [];

const resultado = [];

for (const item of $input.all()) {
  const job = item.json;
  const id = job.job_id;

  if (!id || staticData.seenJobIds.includes(id)) {
    continue; // Já enviada antes
  }

  const title = (job.job_title || '').toLowerCase();
  const desc = (job.job_description || '').toLowerCase();
  const city = (job.job_city || '').toLowerCase();
  const location = (job.job_location || '').toLowerCase();

  const isFeira = /feira\s*de\s*santana|fsa/.test(city) ||
                  /feira\s*de\s*santana|fsa/.test(location) ||
                  /feira\s*de\s*santana/.test(desc);

  const isRemote = job.job_is_remote === true || 
                   /remoto|home\s*office/i.test(title) ||
                   /100%\s*remoto|trabalho\s*remoto/i.test(desc);

  const isAdmin = /administrativ|auxiliar|secretari|escritorio/i.test(title);

  // -------------------------------------------------------------
  // RAMO 4: AUXILIAR ADMINISTRATIVO (Exclusivo Presencial FSA - CLT, Sem ME/PJ)
  // -------------------------------------------------------------
  if (isAdmin) {
    // Regra: Tem que ser em Feira de Santana
    if (!isFeira) continue;
    // Regra: Tem que ser 100% Presencial (não pode ser online/remoto)
    if (isRemote) continue;
    // Regra: Sem ME / Sem PJ (Contratação CLT ou Estágio Direto)
    const isME = /\b(mei|pj|pessoa\s*jurídica|pessoa\s*juridica|microempresa|micro\s*empreendedor|comissionado|autônomo|autonomo)\b/i.test(desc) || /\b(mei|pj)\b/i.test(title);
    if (isME) continue;

    job.categoria = 'admin_fsa';
    staticData.seenJobIds.push(id);
    resultado.push(item);
    continue;
  }

  // -------------------------------------------------------------
  // RAMO 1: VAGA LOCAL DE TI / DEV EM FEIRA DE SANTANA (VIP)
  // -------------------------------------------------------------
  if (isFeira) {
    job.categoria = 'ti_fsa';
    staticData.seenJobIds.push(id);
    resultado.push(item);
    continue;
  }

  // -------------------------------------------------------------
  // VAGAS REMOTAS (Brasil todo)
  // -------------------------------------------------------------
  if (isRemote) {
    const isDev = /desenvolvedor|developer|dev|frontend|front-end|backend|back-end|fullstack|full-stack|software|web|programador|react|node|python|java|javascript/i.test(title) ||
                  /desenvolvedor|programador/i.test(desc);

    if (isDev) {
      // RAMO 2: DESENVOLVEDOR REMOTO
      job.categoria = 'dev_remoto';
      staticData.seenJobIds.push(id);
      resultado.push(item);
    } else {
      // RAMO 3: OUTRAS ÁREAS DE TI REMOTAS (QA, Dados, Suporte, etc.)
      job.categoria = 'ti_geral';
      staticData.seenJobIds.push(id);
      resultado.push(item);
    }
  }
}

if (staticData.seenJobIds.length > 300) {
  staticData.seenJobIds = staticData.seenJobIds.slice(-300);
}

return resultado;

